import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } as primitives } from '@/primitives';
import { default as textUtils } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        // store for cleanup
        if (!root.userData._primitiveInstances) root.userData._primitiveInstances = [];
        root.userData._primitiveInstances.push(instance);
      }
    }
  }

  // Textured plane (CTA background)
  const planeGeom = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.surface || '#0b0b10'),
    transparent: true,
    depthWrite: false,
  });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 42,
      color: config.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    if (root.userData._primitiveInstances) {
      for (const p of root.userData._primitiveInstances) {
        if (p.cleanup) p.cleanup();
      }
    }
    // Dispose plane resources
    planeGeom.dispose();
    planeMat.dispose();
    // Cancel any GSAP timelines (none in this node)
    gsap.globalTimeline.clear();
    // Remove children
    root.traverse((child) => {
      if (child.isMesh && child.geometry) child.geometry.dispose();
      if (child.isMesh && child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}
